<?php
require_once __DIR__.'/includes/admin_check.php';require_admin();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$n=trim($_POST['name']??'');$c=trim($_POST['category']??'');$url=trim($_POST['download_url']??'');if(!$n||!$c||($url&&!filter_var($url,FILTER_VALIDATE_URL)))$err='Thông tin chưa hợp lệ.';else{db()->prepare("INSERT INTO apps(name,category,short_description,description,download_url,status,created_by) VALUES(?,?,?,?,?,?,?)")->execute([$n,$c,trim($_POST['short_description']??''),trim($_POST['description']??''),$url?:null,$_POST['status']==='published'?'published':'draft',current_user()['id']]);flash('Đã thêm ứng dụng.');header('Location: admin.php');exit;}}$pageTitle='Thêm ứng dụng';require __DIR__.'/includes/header.php';?><div class="formbox"><h1>Thêm ứng dụng</h1><p class="error"><?=e($err)?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Tên ứng dụng</label><input name="name" required><label>Danh mục</label><input name="category" required><label>Mô tả ngắn</label><input name="short_description"><label>Mô tả</label><textarea name="description" rows="6"></textarea><label>Link tải HTTPS</label><input type="url" name="download_url"><label>Trạng thái</label><select name="status"><option value="draft">Bản nháp</option><option value="published">Công khai</option></select><button class="btn">Lưu ứng dụng</button></form></div></main></body></html>